using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.TKT.EstadosTickets;namespace GraphApi.Services.TKT.EstadosTickets{    public class EstadosTicketsService : IEstadosTicketsService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public EstadosTicketsService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadEstadosTickets>> GetEstadosTickets(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM tkt.EstadosTickets (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadEstadosTickets>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetEstadosTicketsDynamic(            int? estadoTicketID,            string? estadoTicket,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "EstadoTicketID, EstadoTicket, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM tkt.EstadosTickets (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (estadoTicketID.HasValue)            {                vSql.Append(" AND EstadoTicketID = @EstadoTicketID");                vParameters.Add("EstadoTicketID",estadoTicketID);            }            if (!string.IsNullOrWhiteSpace(estadoTicket))            {                vSql.Append(" AND EstadoTicket LIKE @EstadoTicket");                vParameters.Add("EstadoTicket",$"%{estadoTicket}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadEstadosTickets> CreateEstadosTickets(clCreateEstadosTickets objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO tkt.EstadosTickets                (EstadoTicket, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@EstadoTicket, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.EstadoTicket,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT EstadoTicketID, EstadoTicket, bEliminado                FROM tkt.EstadosTickets (NOLOCK)                WHERE EstadoTicketID = @EstadoTicketID;";            var vReadParams = new { EstadoTicketID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadEstadosTickets>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el EstadosTicket con ID {vNewId}.");            return vCreated;        }        public async Task<clReadEstadosTickets?> UpdateEstadosTickets(clUpdateEstadosTickets objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("EstadoTicketID", objInput.EstadoTicketID);            if (objInput.EstadoTicket is not null)            {                vSets.Add("EstadoTicket = @EstadoTicket");                vParameters.Add("EstadoTicket", objInput.EstadoTicket);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE tkt.EstadosTickets                SET {vSetClause}                WHERE EstadoTicketID = @EstadoTicketID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT EstadoTicketID, EstadoTicket, bEliminado                FROM tkt.EstadosTickets (NOLOCK)                WHERE EstadoTicketID = @EstadoTicketID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadEstadosTickets>(sSelect, new {  objInput.EstadoTicketID });        }        public async Task<bool> DeleteEstadosTickets(int nEstadosTicketsID)        {            const string sSql = @"                DELETE FROM tkt.EstadosTickets                WHERE EstadoTicketID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nEstadosTicketsID });            return vAffected > 0;        }    }}